    caseText: `
    <p>Zenith Mobility Ltd. is considering the introduction of an electric delivery scooter for
    commercial customers. The management accountant warned the board that evaluating the project only
    on the basis of manufacturing cost could result in an incorrect decision because substantial
    expenditure would be incurred before production and after the scooters were sold.</p>
    <p>The design and development team estimated that research, prototype development and testing would
    cost <strong>₹12 lakh</strong>. The company expects to manufacture and sell 4,000 scooters during
    the product's expected life. Manufacturing cost is estimated at <strong>₹28,000 per scooter</strong>.
    Distribution and selling expenses are expected to be ₹4,000 per scooter.</p>
    <p>Because the product is electrically powered, the company expects warranty and after-sales service
    costs of ₹2,500 per scooter. At the end of the product's life, the company expects to incur an
    environmental disposal and recycling cost of ₹800 per scooter.</p>
    <p>The marketing department expects the scooters to be introduced at a relatively high price during
    the introduction stage. As competitors enter the market, management expects selling prices to fall
    during the growth and maturity stages. Management therefore wants to assess profitability over the
    complete product life rather than focusing only on manufacturing margins.</p>
    <p>The expected average selling price over the entire product life is ₹45,000 per scooter. Finance
    has asked the management accountant to calculate the total expected life-cycle profit using the
    available estimates before the company approves the project.</p>
    `,
