    caseText: `
    <p>Vertex Industrial Technologies is developing an automated inspection machine for medium-sized
    manufacturers. The market is already served by three established competitors. After detailed
    market research, Vertex estimates that the machine can be sold for <strong>₹18 lakh</strong> if it
    provides the required inspection accuracy, remote monitoring and basic predictive-maintenance
    functionality.</p>
    <p>The board requires a profit of <strong>18% of the selling price</strong>. The initial product-cost
    model prepared by the engineering department estimated the following costs per machine: electronic
    modules ₹4.20 lakh, mechanical assemblies ₹3.10 lakh, direct labour ₹2.00 lakh, variable production
    overhead ₹1.60 lakh, software and testing ₹1.40 lakh, distribution and customer installation
    ₹1.30 lakh, and expected warranty/service cost ₹0.90 lakh.</p>
    <p>The management accountant pointed out that target costing should consider the entire value chain
    and not merely the manufacturing department. The design team was therefore asked to search for
    alternatives before the product design was frozen.</p>
    <p>Value engineering identified three possible changes. First, an electronic module costing ₹1.20
    lakh could be replaced by an alternative costing ₹0.95 lakh, but the alternative would require an
    additional testing cost of ₹0.05 lakh. Second, redesigning the mechanical assembly could reduce its
    cost by 8%. Third, a supplier agreed to undertake part of the calibration activity, reducing direct
    labour by ₹0.30 lakh but increasing supplier charges included in electronic-module costs by
    ₹0.12 lakh.</p>
    <p>The design leader warned that each change should be evaluated not merely by its apparent cost
    saving but by its effect on total product cost and required customer functionality. Management also
    wanted to know whether the resulting cost would be below the target before approving the design.</p>
    `,
