    caseText: `
    <p>EcoDrive Motors is evaluating two alternative designs for a compact electric vehicle. The company
    expects the vehicle to remain commercially viable for five years. Management believes that the
    accounting profit reported during the manufacturing years may not reflect the actual economics of
    the product because considerable expenditure will be incurred during research, development,
    marketing, warranty support and eventual battery recycling.</p>
    <p><strong>Design Alpha</strong> requires initial research and development expenditure of ₹18 crore.
    Manufacturing cost is expected to be ₹6.20 lakh per vehicle, while distribution, marketing and
    after-sales costs are estimated at ₹1.30 lakh per vehicle. Expected production and sales over the
    product's life are 5,000 vehicles.</p>
    <p><strong>Design Beta</strong> requires initial development expenditure of ₹25 crore. However,
    improved battery architecture reduces manufacturing cost to ₹5.60 lakh per vehicle. Distribution,
    marketing and after-sales costs are ₹1.20 lakh per vehicle.</p>
    <p>Alpha is expected to have a battery recycling and end-of-life cost of ₹30,000 per vehicle,
    whereas Beta's improved battery design reduces this cost to ₹12,000 per vehicle.</p>
    <p>The expected average selling price for Alpha is ₹9.50 lakh per vehicle and for Beta is
    ₹9.80 lakh. Management wants the design that provides the higher total life-cycle profit, rather
    than the design that merely has the lower initial development expenditure.</p>
    `,
