    caseText: `
    <p>Classic Furniture Ltd. produces office furniture for corporate customers. The company sells
    desks, chairs, storage units and conference furniture. Over the past year, competitors have begun
    offering similar furniture at lower prices. Management does not want to reduce the quality of its
    products because long-term customers associate the brand with durability.</p>
    <p>The company therefore established a value-management team. Its first assignment concerned an
    office chair that had already been manufactured and sold for several years. The team examined every
    component and asked whether each feature performed a function that customers valued.</p>
    <p>The review showed that one decorative metal strip increased production cost considerably but
    contributed almost no useful function. Customers did not rely on it for strength, comfort or safety.
    The team recommended eliminating the strip while retaining all essential structural components.</p>
    <p>The team was then asked to participate in the development of a completely new conference chair
    that had not yet entered production. For this product, the designers were encouraged to start by
    identifying the functions customers required and then consider alternative ways of providing those
    functions.</p>
    <p>One designer proposed simply modifying the existing office chair design. Another suggested
    analysing the required functions from the beginning and considering whether fewer components,
    different materials or a different assembly method could provide the same customer benefit.</p>
    <p>Management wanted employees to understand that the two exercises were related but were not
    identical because they were being performed at different stages of the product's life.</p>
    `,
