    caseText: `
    <p>BrightWave Electronics Ltd. develops smart home security systems. The company evaluates product
    profitability every quarter using manufacturing cost, selling price and current-period marketing
    expenditure. The chief executive recently questioned whether this approach was giving management a
    complete picture of profitability.</p>
    <p>The company spends considerable amounts on research, prototype development and testing before a
    product is launched. During the introduction stage, significant expenditure is incurred on advertising,
    customer education, channel development and demonstrations even though sales volume is initially low.</p>
    <p>Once the product enters growth, sales increase rapidly and competitors begin introducing similar
    systems. The company then spends more on product improvements, software updates, customer retention
    and distribution expansion.</p>
    <p>During maturity, sales continue but the rate of growth slows. Competitors frequently offer price
    reductions, additional features and promotional incentives. The company must decide whether to
    improve the product, reduce price, strengthen distribution or differentiate the product.</p>
    <p>Eventually, new technologies may make the existing system less attractive. Sales decline and
    management must decide whether to reduce the price, serve a smaller loyal market, reposition the
    product, use it as a replacement platform or discontinue it.</p>
    <p>The management accountant explained that the complete product life should therefore be considered
    when analysing profitability. The company also wanted to use the resulting information for planning
    and control rather than merely producing a historical report.</p>
    `,
