    caseText: `
    <p>Zenith Communication Devices Ltd. is developing a professional communication terminal for large
    logistics companies. The company has historically measured engineering performance by whether
    designers could meet technical specifications within the internal cost estimate prepared by the
    finance department.</p>
    <p>For the new product, the marketing team conducted extensive research before design was finalised.
    Customers indicated that they valued communication reliability, battery life, software compatibility
    and ease of maintenance. They showed considerably less interest in decorative design features that
    engineers had originally included to differentiate the product visually.</p>
    <p>The marketing department also found that two major competitors were expected to launch similar
    products within twelve months. The sales team therefore warned that customers would resist a price
    substantially above the expected competitor range.</p>
    <p>The finance department initially proposed using the company's normal cost-plus system. The
    management accountant rejected this approach because the resulting price would be determined primarily
    by internal costs rather than by market conditions.</p>
    <p>A target-costing team was established. The team included marketing, engineering, production,
    purchasing, finance, logistics and after-sales service. A major supplier was also invited because
    the supplier designed a critical electronic subsystem.</p>
    <p>During the first design review, engineering members argued that reducing the number of product
    features could weaken the company's reputation for innovation. Marketing responded that eliminating
    features customers did not value could actually improve the value proposition by allowing resources
    to be concentrated on reliability and battery life.</p>
    <p>The team then discovered that several costs were committed during the design stage. Changing the
    product after production began would be considerably more expensive than changing it before the
    design was frozen. Management therefore asked the team to close the target-cost gap before production.</p>
    <p>The project leader warned against assigning the entire burden of cost reduction to the purchasing
    department. Some costs could be reduced through product design, some through manufacturing methods,
    some through supplier cooperation and others through eliminating non-value-added activities across
    the value chain.</p>
    `,
